begin
 perform pg_advisory_xact_lock(hashtext('hzad-listening-01-06-review-v5'));
 select jsonb_build_array((select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from auth.users t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.purchase_entitlements t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.academy_learning_progress t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.wallets t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.requests t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.ledger t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.policy t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.activities t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.testing_grants t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.calls t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_exams.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.published_papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.navigation t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_speaking.calls t)) into protected_before;
 select coalesce(jsonb_object_agg(id||':'||version,md5(content::text)),'{}') into old_before
  from academy_tcf_listening.papers where version not in ('tcf-listening-2026-11-test01-v5','tcf-listening-2026-11-test02-v5','tcf-listening-2026-11-test03-v5','tcf-listening-2026-11-test04-v5','tcf-listening-2026-11-test05-v5','tcf-listening-2026-11-test06-v5');
 select coalesce(jsonb_object_agg(test_id,version),'{}') into other_before
  from academy_tcf_listening.published where test_id not in ('tcf-listening-01','tcf-listening-02','tcf-listening-03','tcf-listening-04','tcf-listening-05','tcf-listening-06');
 select md5(pg_get_functiondef('public.academy_tcf_listening_command(text,uuid,jsonb)'::regprocedure)) into engine_before;
 for item in select value from jsonb_array_elements(wanted) loop
  select content into prior from academy_tcf_listening.papers where id=item->>'id' and version=item->>'version';
  if found and prior is distinct from item then raise exception 'Immutable review version differs: %',item->>'id';end if;
  select content into prior from academy_tcf_listening.papers where id=item->>'id'
   and version=case when item->>'id'='tcf-listening-01' then 'tcf-listening-2026-11-v1' else 'tcf-listening-2026-11-test'||right(item->>'id',2)||'-v1' end;
  if not found then raise exception 'Historical bank missing';end if;
  if jsonb_array_length(item->'questions')<>39 or (item->>'seconds')::int<>2100
   or (select sum((q->>'slotSeconds')::numeric) from jsonb_array_elements(item->'questions') q)<>2100
   or exists(select 1 from jsonb_array_elements(item->'questions') with ordinality as x(q,n)
    where (q->>'number')::int<>n or jsonb_array_length(q->'options')<>4 or q->>'correct' not in ('A','B','C','D')
     or coalesce((q->>'audioSeconds')::numeric,0)<=0 or (q->>'audioSeconds')::numeric+12>(q->>'slotSeconds')::numeric)
   then raise exception 'Invalid complete bank';end if;
  if exists(select 1 from jsonb_array_elements(item->'questions') q join jsonb_array_elements(prior->'questions') oldq on q->>'number'=oldq->>'number'
   where q->'slotSeconds' is distinct from oldq->'slotSeconds' or q->'kind' is distinct from oldq->'kind')then raise exception 'Historical format/timing changed';end if;
  insert into academy_tcf_listening.papers(id,version,content) values(item->>'id',item->>'version',item) on conflict(id,version) do nothing;
  insert into academy_tcf_listening.published(test_id,version) values(item->>'id',item->>'version') on conflict(test_id) do update set version=excluded.version
   where academy_tcf_listening.published.version is distinct from excluded.version;
 end loop;
 select jsonb_build_array((select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from auth.users t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.purchase_entitlements t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.academy_learning_progress t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.wallets t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.requests t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.ledger t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.policy t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.activities t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.testing_grants t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.calls t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_exams.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.published_papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.navigation t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_speaking.calls t)) into protected_after;
 select coalesce(jsonb_object_agg(id||':'||version,md5(content::text)),'{}') into old_after
  from academy_tcf_listening.papers where version not in ('tcf-listening-2026-11-test01-v5','tcf-listening-2026-11-test02-v5','tcf-listening-2026-11-test03-v5','tcf-listening-2026-11-test04-v5','tcf-listening-2026-11-test05-v5','tcf-listening-2026-11-test06-v5');
 select coalesce(jsonb_object_agg(test_id,version),'{}') into other_after
  from academy_tcf_listening.published where test_id not in ('tcf-listening-01','tcf-listening-02','tcf-listening-03','tcf-listening-04','tcf-listening-05','tcf-listening-06');
 select md5(pg_get_functiondef('public.academy_tcf_listening_command(text,uuid,jsonb)'::regprocedure)) into engine_after;
 if protected_before is distinct from protected_after or old_before is distinct from old_after or other_before is distinct from other_after or engine_before is distinct from engine_after
  then raise exception 'Preservation check failed; review publication rolled back';end if;
 if exists(select 1 from jsonb_array_elements(wanted) p where not exists(select 1 from academy_tcf_listening.papers b join academy_tcf_listening.published v on v.test_id=b.id and v.version=b.version
  where b.id=p->>'id' and b.version=p->>'version' and b.content=p))then raise exception 'Exact review publication failed';end if;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='academy_tcf_listening' and c.relkind='r' and not c.relrowsecurity)
  or has_table_privilege('anon','academy_tcf_listening.papers','select') or has_table_privilege('authenticated','academy_tcf_listening.papers','select')
  then raise exception 'Private bank protection changed';end if;
end;
$publish_six$;
